-- Build139-06; generated by Supabase CLI at current UTC. Not applied by source preparation.
-- Owner JWT + relay/session ownership remain the existing authorisation boundary.
-- The service validates canonical geometry; SQL bounds the envelope and opaque revision.
ALTER TABLE public.pi_anchor_sessions
    ADD COLUMN IF NOT EXISTS safe_area jsonb,
    ADD COLUMN IF NOT EXISTS safe_area_revision text,
    ADD COLUMN IF NOT EXISTS safe_area_vessel_id text;

ALTER TABLE public.pi_anchor_sessions
    ADD CONSTRAINT pi_anchor_safe_area_envelope_v1 CHECK (
        safe_area IS NULL OR (
            jsonb_typeof(safe_area) = 'object'
            AND safe_area ?& ARRAY['version','frame','zone']
            AND (safe_area - ARRAY['version','frame','zone']) = '{}'::jsonb
            AND jsonb_typeof(safe_area -> 'version') = 'number'
            AND safe_area ->> 'version' = '1'
            AND jsonb_typeof(safe_area -> 'frame') = 'object'
            AND jsonb_typeof(safe_area -> 'zone') IN ('object','null')
            AND octet_length(safe_area::text) <= 8192
            AND safe_area_revision IS NOT NULL
        )
    ),
    ADD CONSTRAINT pi_anchor_safe_area_revision_uuid CHECK (
        safe_area_revision IS NULL OR safe_area_revision ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    ADD CONSTRAINT pi_anchor_safe_area_vessel_length CHECK (
        safe_area_vessel_id IS NULL OR length(safe_area_vessel_id) BETWEEN 1 AND 128
    ),
    ADD CONSTRAINT pi_anchor_safe_area_legacy_nulls CHECK (
        safe_area IS NOT NULL OR (safe_area_revision IS NULL AND safe_area_vessel_id IS NULL)
    );
COMMENT ON COLUMN public.pi_anchor_sessions.safe_area IS
    'Owner-authorised manual boundary or explicit circle with exact frame; canonical parser validates every read. SQL null is the legacy circle protocol.';
COMMENT ON COLUMN public.pi_anchor_sessions.safe_area_revision IS
    'Owner-issued watch/edit UUID echoed by the Pi; stale reports cannot renew a different boundary.';
COMMENT ON COLUMN public.pi_anchor_sessions.safe_area_vessel_id IS
    'Selected vessel identifier for the owner-authorised boundary; null is an explicit watch without a selected fleet vessel.';

-- No new client privilege or SECURITY DEFINER. The Edge Function has already
-- verified its owner JWT/scoped Pi token. These service-only operations serialize
-- on one relay, then lock its binding, then its watch session (the same order as
-- the unchanged heartbeat). The advisory lock also covers a not-yet-created row.
CREATE FUNCTION public.authorise_pi_anchor_area(
    p_relay_id TEXT, p_owner_id UUID, p_session_code TEXT,
    p_expected JSONB, p_explicit_area BOOLEAN,
    p_safe_area JSONB, p_safe_area_revision TEXT, p_safe_area_vessel_id TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
    b public.pi_anchor_sessions%ROWTYPE;
    written public.pi_anchor_sessions%ROWTYPE;
    had_binding BOOLEAN;
    session_owner UUID;
    session_expiry TIMESTAMPTZ;
    stamp TIMESTAMPTZ;
    target_area JSONB;
    target_revision TEXT;
    target_vessel TEXT;
BEGIN
    IF current_user <> 'service_role' THEN RAISE insufficient_privilege; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(p_relay_id, 13906));
    SELECT * INTO b FROM public.pi_anchor_sessions WHERE relay_id = p_relay_id FOR UPDATE;
    had_binding := FOUND;
    IF had_binding THEN
        IF p_expected IS NULL
            OR p_expected ->> 'owner_id' IS DISTINCT FROM b.owner_id::text
            OR p_expected ->> 'session_code' IS DISTINCT FROM b.session_code
            OR (p_explicit_area AND (
                p_expected -> 'safe_area' IS DISTINCT FROM COALESCE(b.safe_area, 'null'::jsonb)
                OR p_expected ->> 'safe_area_revision' IS DISTINCT FROM b.safe_area_revision
                OR p_expected ->> 'safe_area_vessel_id' IS DISTINCT FROM b.safe_area_vessel_id
            )) THEN
            RETURN jsonb_build_object('conflict', true);
        END IF;
    ELSIF p_expected IS NOT NULL THEN
        RETURN jsonb_build_object('conflict', true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.pi_diary_relays
        WHERE relay_id = p_relay_id AND owner_id = p_owner_id AND enabled) THEN RETURN NULL; END IF;
    SELECT owner_user_id, expires_at INTO session_owner, session_expiry
        FROM public.anchor_watch_sessions WHERE session_code = p_session_code FOR UPDATE;
    stamp := clock_timestamp();
    IF NOT FOUND OR session_owner IS DISTINCT FROM p_owner_id OR session_expiry <= stamp THEN RETURN NULL; END IF;
    IF p_explicit_area THEN
        IF p_safe_area IS NULL OR p_safe_area_revision IS NULL THEN
            RETURN jsonb_build_object('invalid_safe_area', true);
        END IF;
        IF had_binding AND b.safe_area_revision = p_safe_area_revision
            AND (b.safe_area IS DISTINCT FROM p_safe_area OR b.safe_area_vessel_id IS DISTINCT FROM p_safe_area_vessel_id) THEN
            RETURN jsonb_build_object('conflict', true);
        END IF;
        target_area := p_safe_area;
        target_revision := p_safe_area_revision;
        target_vessel := p_safe_area_vessel_id;
    ELSIF had_binding AND b.owner_id = p_owner_id AND b.session_code = p_session_code THEN
        -- A legacy renewal preserves the CURRENT boundary under the row lock,
        -- not the stale copy the caller read before a concurrent area edit.
        target_area := b.safe_area;
        target_revision := b.safe_area_revision;
        target_vessel := b.safe_area_vessel_id;
    END IF;
    IF had_binding THEN
        UPDATE public.pi_anchor_sessions SET owner_id = p_owner_id, session_code = p_session_code,
            authorised_at = stamp, expires_at = LEAST(stamp + interval '6 hours', session_expiry),
            last_heartbeat_at = NULL, contact_alarm_at = NULL, gps_alarm_at = NULL,
            expiry_alarm_at = NULL, gps_available = false, is_dragging = false,
            safe_area = target_area, safe_area_revision = target_revision, safe_area_vessel_id = target_vessel
            WHERE relay_id = p_relay_id RETURNING * INTO written;
    ELSE
        INSERT INTO public.pi_anchor_sessions(relay_id,owner_id,session_code,authorised_at,expires_at,
            safe_area,safe_area_revision,safe_area_vessel_id)
            VALUES(p_relay_id,p_owner_id,p_session_code,stamp,LEAST(stamp + interval '6 hours',session_expiry),
                target_area,target_revision,target_vessel)
            ON CONFLICT (relay_id) DO NOTHING RETURNING * INTO written;
        IF NOT FOUND THEN RETURN jsonb_build_object('conflict', true); END IF;
    END IF;
    RETURN jsonb_build_object('authorised',true,'safeZoneVersion',1,
        'expires_at',written.expires_at,'session_expires_at',session_expiry,
        'expires_in_ms',GREATEST(0,extract(epoch FROM written.expires_at - clock_timestamp()) * 1000),
        'safe_area',written.safe_area,'safe_area_revision',written.safe_area_revision,
        'safe_area_vessel_id',written.safe_area_vessel_id);
END;
$$;
REVOKE ALL ON FUNCTION public.authorise_pi_anchor_area(TEXT,UUID,TEXT,JSONB,BOOLEAN,JSONB,TEXT,TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.authorise_pi_anchor_area(TEXT,UUID,TEXT,JSONB,BOOLEAN,JSONB,TEXT,TEXT) TO service_role;

CREATE FUNCTION public.record_pi_anchor_area_heartbeat(
    p_relay_id TEXT, p_session_code TEXT, p_owner_id UUID,
    p_safe_area JSONB, p_safe_area_revision TEXT, p_safe_area_vessel_id TEXT,
    p_gps_available BOOLEAN, p_drag BOOLEAN,
    p_distance_m REAL, p_swing_radius_m REAL, p_lat REAL, p_lon REAL
) RETURNS JSONB LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE b public.pi_anchor_sessions%ROWTYPE;
BEGIN
    IF current_user <> 'service_role' THEN RAISE insufficient_privilege; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(p_relay_id, 13906));
    SELECT * INTO b FROM public.pi_anchor_sessions WHERE relay_id = p_relay_id FOR UPDATE;
    IF NOT FOUND OR b.owner_id IS DISTINCT FROM p_owner_id OR b.session_code IS DISTINCT FROM p_session_code
        OR b.expires_at <= clock_timestamp()
        OR b.safe_area IS DISTINCT FROM p_safe_area
        OR b.safe_area_revision IS DISTINCT FROM p_safe_area_revision
        OR b.safe_area_vessel_id IS DISTINCT FROM p_safe_area_vessel_id THEN RETURN NULL; END IF;
    -- The actual existing lease/alarm implementation runs inside this SAME
    -- transaction and locked row. Its old signature/body/grants stay unchanged.
    RETURN public.record_pi_anchor_heartbeat(p_relay_id,p_session_code,p_owner_id,
        p_gps_available,p_drag,p_distance_m,p_swing_radius_m,p_lat,p_lon);
END;
$$;
REVOKE ALL ON FUNCTION public.record_pi_anchor_area_heartbeat(TEXT,TEXT,UUID,JSONB,TEXT,TEXT,BOOLEAN,BOOLEAN,REAL,REAL,REAL,REAL) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_pi_anchor_area_heartbeat(TEXT,TEXT,UUID,JSONB,TEXT,TEXT,BOOLEAN,BOOLEAN,REAL,REAL,REAL,REAL) TO service_role;

CREATE FUNCTION public.stop_pi_anchor_area(p_relay_id TEXT,p_session_code TEXT,p_owner_id UUID,p_expected JSONB)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE b public.pi_anchor_sessions%ROWTYPE;
BEGIN
    IF current_user <> 'service_role' THEN RAISE insufficient_privilege; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(p_relay_id, 13906));
    IF NOT EXISTS (SELECT 1 FROM public.pi_diary_relays
        WHERE relay_id = p_relay_id AND owner_id = p_owner_id AND enabled) THEN RETURN false; END IF;
    SELECT * INTO b FROM public.pi_anchor_sessions WHERE relay_id = p_relay_id FOR UPDATE;
    IF FOUND THEN
        IF b.owner_id IS DISTINCT FROM p_owner_id OR b.session_code IS DISTINCT FROM p_session_code
            OR p_expected IS NULL
            OR p_expected -> 'safe_area' IS DISTINCT FROM COALESCE(b.safe_area,'null'::jsonb)
            OR p_expected ->> 'safe_area_revision' IS DISTINCT FROM b.safe_area_revision
            OR p_expected ->> 'safe_area_vessel_id' IS DISTINCT FROM b.safe_area_vessel_id THEN RETURN false; END IF;
        DELETE FROM public.pi_anchor_sessions WHERE relay_id = p_relay_id;
    END IF;
    UPDATE public.anchor_alarm_events SET resolved_at = clock_timestamp()
        WHERE session_code = p_session_code AND user_id = p_owner_id AND resolved_at IS NULL;
    RETURN true;
END;
$$;
REVOKE ALL ON FUNCTION public.stop_pi_anchor_area(TEXT,TEXT,UUID,JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.stop_pi_anchor_area(TEXT,TEXT,UUID,JSONB) TO service_role;
